import importlib.util,json,pathlib,tempfile,unittest,copy
ROOT=pathlib.Path(__file__).resolve().parents[1];spec=importlib.util.spec_from_file_location('walk_align',ROOT/'scripts/integrate-walk-alignments.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
class Integration(unittest.TestCase):
 def setup_root(self):
  temp=tempfile.TemporaryDirectory();self.addCleanup(temp.cleanup);r=pathlib.Path(temp.name);(r/'data').mkdir();(r/'dist').mkdir()
  s={'id':'central108_tread_0','polygon':[[0,0,0],[2,0,0],[2,2,0]],'triangles':[[0,1,2]]};road={'name':'CAMPUS_ROAD 474301324','points':[[0,0,0],[2,0,0]],'width':2};path={'id':'central108','points':[[.2,.2,0],[1,.2,0]]};nav={'walkableSurfaces':[s],'pedestrianPaths':[path],'roads':[road],'landmarks':[]};world=copy.deepcopy(nav)
  for x in world['walkableSurfaces']:x['polygon']=[mod.cv(p) for p in x['polygon']]
  for key in ['roads','pedestrianPaths']:
   for x in world[key]:x['points']=[mod.cv(p) for p in x['points']]
  world['destinations']=[];world['extraCars']=[{'unchanged':True}];mod.write(r/'data/campus-navigation.json',nav);(r/'dist/world-config.js').write_text('// fixture\nexport const WORLD = '+json.dumps(world)+';\n');mod.write(r/'data/entrance-sync-report.json',{'records':[],'destinationChanges':[]});mod.write(r/'data/walking-road-graph-3d.json',{'nodes':[[0,0,0],[2,0,0]],'edges':[{'a':0,'b':1,'osm_id':'474301324','length':2}]});return r,nav
 def test_scoped_exact_support_and_path_idempotence(self):
  r,nav=self.setup_root();sf=copy.deepcopy(nav['walkableSurfaces'][0]);sf['polygon']=[[p[0],p[1],.2] for p in sf['polygon']];data={'geometry_modified':False,'remove_surface_prefixes':['central108_'],'walkableSurfaces':[sf],'pedestrianPaths':[{'id':'central108','points':[[.2,.2,.2],[1,.2,.2]]}],'entrance_route_overrides':[],'route_audit':[{'id':'central108','requires_geometry_review':False}]};source=r/'walk.json';mod.write(source,data);mod.apply(r,source);first=(r/'dist/world-config.js').read_bytes();mod.apply(r,source);self.assertEqual(first,(r/'dist/world-config.js').read_bytes());self.assertEqual(json.loads((r/'data/campus-navigation.json').read_text())['walkableSurfaces'][0],sf)
 def test_scope_escape_is_rejected(self):
  r,nav=self.setup_root();data={'geometry_modified':False,'remove_surface_prefixes':['central108_'],'walkableSurfaces':[{**nav['walkableSurfaces'][0],'id':'unrelated'}],'pedestrianPaths':[]};source=r/'bad.json';mod.write(source,data)
  with self.assertRaisesRegex(ValueError,'escaped'):mod.apply(r,source)
 def test_it_retirement_and_clipping_preserve_outside(self):
  r,nav=self.setup_root();data={'vehicle_access':False,'source_way_ids':['474301324'],'replacement_polygon_xy':[[[0,0],[1,0],[1,1],[0,1]]],'walkableSurfaces':[{'id':'IT138_high','polygon':[[0,0,1],[1,0,1],[1,1,1]],'triangles':[[0,1,2]]}],'updatedPedestrianPaths':[{'id':'IT138_approach','points':[[0,0,1],[1,1,1]]}],'updatedWalkingNodes':[{'index':0,'before':[0,0,0],'position':[0,0,1]}],'retiredWalkingEdges':[{'a':0,'b':1,'osm_id':'474301324','before_endpoints':[[0,0,0],[2,0,0]]}]};source=r/'it.json';mod.write(source,data);mod.apply(r,it_source=source);out=json.loads((r/'data/campus-navigation.json').read_text());self.assertEqual(len(out['walkableSurfaces']),2);self.assertEqual(out['roads'],[]);graph=json.loads((r/'data/walking-road-graph-3d.json').read_text());self.assertEqual(graph['nodes'],[[0,0,1],[2,0,0]]);self.assertEqual(graph['edges'],[]);first=(r/'dist/world-config.js').read_bytes();mod.apply(r,it_source=source);self.assertEqual(first,(r/'dist/world-config.js').read_bytes())
 def test_public_paths_preserve_support_and_are_idempotent(self):
  r,nav=self.setup_root();ids=['public_rose_spine','red_track_perimeter_loop'];paths=[{'id':i,'points':[[0,0,0],[1,0,0]]} for i in ids];nav['pedestrianPaths']+=paths;mod.write(r/'data/campus-navigation.json',nav)
  wp,head,world=mod.load_world(r);world['pedestrianPaths']+=[{**p,'points':[mod.cv(v) for v in p['points']]} for p in paths];wp.write_text(head+'\nexport const WORLD = '+json.dumps(world)+';\n');before=copy.deepcopy(world['walkableSurfaces'])
  data={'schema':'public-walk-clearance-v1','replacePedestrianPathIds':ids,'pedestrianPaths':[{**p,'points':[[0,0,.1],[1,0,.2]]} for p in paths],'walkableSurfaces':[],'collisionBoxes':[]};source=r/'public.json';mod.write(source,data);mod.apply(r,public_source=source);first=wp.read_bytes();mod.apply(r,public_source=source);self.assertEqual(first,wp.read_bytes());self.assertEqual(mod.load_world(r)[2]['walkableSurfaces'],before)
 def test_finite_paving_preserves_other_nodes_and_layered_floor(self):
  r,nav=self.setup_root();mod.write(r/'data/native-export-manifest.json',{'sidecar_sha256':{'source.json':'abc'}})
  data={'schema':'final-pedestrian-finite-surface-1','source_road_graph':'source.json','source_road_graph_sha256':'abc','added_connector_width_m':1.6,'added_connector_path':[[0,0,.2],[1,0,.3]],'walking_node_replacements':[{'index':0,'original_position':[0,0,0],'new_position':[0,0,.2]}]};source=r/'finite.json';mod.write(source,data);mod.apply(r,pedestrian_source=source)
  graph=json.loads((r/'data/walking-road-graph-3d.json').read_text());self.assertEqual(graph['nodes'],[[0,0,.2],[2,0,0]]);out=json.loads((r/'data/campus-navigation.json').read_text());self.assertEqual(out['walkableSurfaces'],nav['walkableSurfaces']);self.assertEqual(out['roads'][0]['points'][0],[0,0,.2]);self.assertEqual(out['pedestrianPaths'][-1]['id'],'final_mapped_footway_947734765');self.assertFalse(out['pedestrianPaths'][-1]['vehicle_access']);before=(r/'dist/world-config.js').read_bytes();mod.apply(r,pedestrian_source=source);self.assertEqual(before,(r/'dist/world-config.js').read_bytes())
  data['source_road_graph_sha256']='different';mod.write(source,data)
  with self.assertRaisesRegex(ValueError,'binding differs'):mod.apply(r,pedestrian_source=source)
 def test_mapped_connector_replaces_exact_road_and_densifies_only_its_edges(self):
  r,nav=self.setup_root();nav['roads'][0]['osm_id']='947734765';mod.write(r/'data/campus-navigation.json',nav);wp,header,world=mod.load_world(r);world['roads'][0]['osm_id']='947734765';wp.write_text(header+'\nexport const WORLD = '+json.dumps(world)+';\n');gp=r/'data/walking-road-graph-3d.json';graph=json.loads(gp.read_text());graph['edges'][0]['osm_id']='947734765';mod.write(gp,graph)
  mod.write(r/'data/native-export-manifest.json',{'sidecar_sha256':{'graph.json':'graph-sha','nav.json':'nav-sha'}});points=[[0,0,.2],[1,0,.3],[2,0,0]]
  data={'schema':'final-pedestrian-finite-surface-1','source_road_graph':'graph.json','source_road_graph_sha256':'graph-sha','walking_node_replacements':[{'index':0,'original_position':[0,0,0],'new_position':[0,0,.2]}],'added_connector_path':points,'added_connector_width_m':1.6,'mapped_connector_replacement':{'osm_id':'947734765','source_navigation_path':'nav.json','source_navigation_sha256':'nav-sha','source_road_index':0,'source_road_record':nav['roads'][0],'source_graph_edges':[{'index':0,'source_record':graph['edges'][0],'source_node_positions':graph['nodes'],'points':points,'width_m':1.6}],'points':points,'width_m':1.6,'support_surface_objects':['actual_paving']}}
  source=r/'mapped.json';mod.write(source,data);baseline={p:p.read_bytes() for p in [gp,wp,r/'data/campus-navigation.json']};mod.apply(r,pedestrian_source=source);first=gp.read_bytes();out=json.loads(first);self.assertEqual(len(out['nodes']),3);self.assertEqual(len(out['edges']),2);self.assertEqual(out['nodes'][1],[2,0,0]);self.assertEqual(json.loads((r/'data/campus-navigation.json').read_text())['roads'][0]['points'],points);mod.apply(r,pedestrian_source=source);self.assertEqual(first,gp.read_bytes())
  for p,raw in baseline.items():p.write_bytes(raw)
  mod.apply(r,pedestrian_source=source);self.assertEqual(first,gp.read_bytes())
 def test_single_bound_arch_detour_and_unrelated_xy_rejection(self):
  r,nav=self.setup_root();old=[1,0,0];new=[1,.5,.2];points=[[0,0,0],new,[2,0,0]]
  nav['roads'][0].update(osm_id='947734765',points=[[0,0,0],old,[2,0,0]]);mod.write(r/'data/campus-navigation.json',nav)
  wp,head,world=mod.load_world(r);world['roads'][0].update(osm_id='947734765',points=[mod.cv(p) for p in nav['roads'][0]['points']]);wp.write_text(head+'\nexport const WORLD = '+json.dumps(world)+';\n')
  nodes=[[0,0,0],[2,0,0]]+[[50+i,50,0] for i in range(1034)]+[old];edges=[{'a':0,'b':1036,'osm_id':'947734765','length':1},{'a':1036,'b':1,'osm_id':'947734765','length':1}];gp=r/'data/walking-road-graph-3d.json';mod.write(gp,{'nodes':nodes,'edges':edges})
  mod.write(r/'data/native-export-manifest.json',{'sidecar_sha256':{'graph.json':'graph-sha','nav.json':'nav-sha'}})
  adjustment={'index':1036,'original_position':old,'new_position':new,'maximum_xy_shift_m':.5,'source_way_id':'947734765','reason':'Keep the original arch and stay inside the actual paved area'}
  data={'schema':'final-pedestrian-finite-surface-1','source_road_graph':'graph.json','source_road_graph_sha256':'graph-sha','walking_node_replacements':[{'index':1036,'original_position':old,'new_position':new}],'walking_node_xy_adjustments':[adjustment],'added_connector_path':points,'added_connector_width_m':1.6,'mapped_connector_replacement':{'osm_id':'947734765','source_navigation_path':'nav.json','source_navigation_sha256':'nav-sha','source_road_index':0,'source_road_record':nav['roads'][0],'source_graph_edges':[{'index':i,'source_record':e,'points':[points[i],points[i+1]]} for i,e in enumerate(edges)],'points':points,'width_m':1.6,'support_surface_objects':['actual_rose_paving']}}
  source=r/'detour.json';mod.write(source,data);before_nodes=copy.deepcopy(nodes);mod.apply(r,pedestrian_source=source);result=json.loads(gp.read_text());self.assertEqual(result['nodes'][1036],new);self.assertEqual(result['nodes'][:1036],before_nodes[:1036]);first=gp.read_bytes();mod.apply(r,pedestrian_source=source);self.assertEqual(first,gp.read_bytes())
  graph={'nodes':nodes,'edges':edges};bad=copy.deepcopy(data);bad['walking_node_xy_adjustments'][0]['index']=0
  with self.assertRaisesRegex(ValueError,'escaped'):mod.validate_paving_xy_adjustments(bad,bad['walking_node_replacements'],graph)
  bad=copy.deepcopy(data);bad['walking_node_xy_adjustments'][0]['maximum_xy_shift_m']=.6
  with self.assertRaisesRegex(ValueError,'half-metre'):mod.validate_paving_xy_adjustments(bad,bad['walking_node_replacements'],graph)
  bad=copy.deepcopy(data);bad['walking_node_xy_adjustments'][0]['new_position']=[1,.4,.2]
  with self.assertRaisesRegex(ValueError,'exact source/output'):mod.validate_paving_xy_adjustments(bad,bad['walking_node_replacements'],graph)
  graph['edges'].append({'a':1036,'b':2,'osm_id':'unrelated'})
  with self.assertRaisesRegex(ValueError,'unrelated adjacent'):mod.validate_paving_xy_adjustments(data,data['walking_node_replacements'],graph)
 def test_exact_retired_triangles_preserve_other_height_and_outside(self):
  tris=[[[10*i,0,0],[10*i+1,0,.1],[10*i,1,0]] for i in range(15)]
  contract={'world_triangles':tris,'per_triangle_z_ranges_m':[[0,.1] for _ in tris],'match_height_tolerance_m':.03,'source_osm_ids':['1291221161','1485907425'],'source_object':'CAMPUS_CONTINUOUS pedestrian paving','preserve_group50':True}
  floor={'id':'generic1291221161','polygon':[[0,0,0],[2,0,.2],[0,2,0]],'triangles':[[0,1,2]]};upper={**copy.deepcopy(floor),'id':'original_stair','polygon':[[p[0],p[1],p[2]+.5] for p in floor['polygon']]};below={**copy.deepcopy(floor),'id':'lower_terrain','polygon':[[p[0],p[1],p[2]-.5] for p in floor['polygon']]}
  out,cuts=mod.retire_exact_generic([floor,upper,below],contract);self.assertEqual(out[1:],[upper,below]);self.assertAlmostEqual(cuts[0]['removed_projected_area_m2'],.5);again,changes=mod.retire_exact_generic(out,contract);self.assertEqual(again,out);self.assertEqual(changes,[])
  with self.assertRaisesRegex(ValueError,'Unrelated support'):mod.retire_exact_generic([{**floor,'id':'actual_authored_stair'}],contract)
  bad=copy.deepcopy(contract);bad['per_triangle_z_ranges_m'][0]=[0,1]
  with self.assertRaisesRegex(ValueError,'height range'):mod.retire_exact_generic([floor],bad)
if __name__=='__main__':unittest.main()
